-- ─────────────────────────────────────────────────────────────
--  THE OLD WEBSITE'S NEWS — part 7 of 7: 68 articles kept as drafts (not live)
--  Generated by scripts/import-old-news.py from Rich's export of the old WordPress database.
--  Run the news files in order, after the other files in supabase/legacy/ (SQL Editor → paste → Run), each once.
--
--  All 528 old articles: 186 league and competition articles from 2019 on go live, with their real dates.
--  The other 342 wait in Admin → News as drafts (Rich, round 30): Professional Snooker, CueViews,
--  Snooker Memories, and the old archive — whose articles all carry the date 1 January 2014 on the old site
--  (their real dates were lost long ago). Tick "Published" on any of them to put it on the website.
--  The text keeps its paragraphs, the opening paragraph and the pull quote. Pictures are not brought across
--  (Rich is sorting them): real-data/legacy/news-pictures.csv says which article had which picture.
--  None is "featured", so the News page and the banner keep showing the newest articles.
--  Nothing already on the website is changed. All one transaction.
-- ─────────────────────────────────────────────────────────────
begin;

do $$ begin
  if exists (select 1 from articles where slug in ('strugglers-take-the-runabout-shield', 'stuff-of-legend', 'superb-hamilton-wins-first-ranking-title', 'taylors-no-turnip-with-fine-88-break', 'team-player-profiles-to-feature-ever-week')) then
    raise exception 'This part of the old news is already in: nothing to do.';
  end if;
end $$;

insert into categories (name, sort)
  select r.name, 100 + row_number() over (order by r.name) from (values
  ('Competitions'),
  ('Cue View'),
  ('League Meetings'),
  ('League News'),
  ('Match Reports'),
  ('Professional Snooker'),
  ('Snooker Memories')) r(name)
  where not exists (select 1 from categories c where lower(c.name) = lower(r.name));

create temp table _news (title text, slug text, category text, more_categories jsonb, excerpt text, lead text, quote_text text, body text, published_at date, is_published boolean, author text) on commit drop;
insert into _news values
  ('Strugglers take the Runabout Shield', 'strugglers-take-the-runabout-shield', 'Match Reports', '[]'::jsonb, 'Basement boys Tregonissey ‘B’ really put a dent in Bugle ‘A’s title hopes returning home with a 3-2 win and the Runabout Shield.', null, 'The Runabout Shield in the Rees League is now at lowly Lostwithiel after they beat table toppers Mevagissey ‘C’.', 'Basement boys Tregonissey ‘B’ really put a dent in Bugle ‘A’s title hopes returning home with a 3-2 win and the Runabout Shield.

more Phil Hooley and Andrew Gooch put Treggy 2-0 up beat Paul Sturtridge and Gary Spencer. Ian Ball and Andrew Best, who knocked in a 39 break, restored parity only for Mike Hooley to beat Ian Powell for a great win. Bugle’s defeat was made more significant by Tregonissey ‘A’ taking all give points against Mevagissey ‘D’ to move eight points clear at the top Barrie McIntosh’s 35 break was the highlight of the evening. Geoff Hawken and Matt Green put Bethel ‘A’ ahead at Pelynt and the win was secured as Garry Stephens had a 27 clearance to see of Phil Ormond. The home side took the last two with excellent potting from Richard Broad and Keith Armatage. Darren Lock’s 38 and Matt Vessey’s 44 put St Neot 2-0 up at home to Mevagissey ‘B’. Ben Rothwell beat Chris Perring to pull one back but Anthony Maddams and Steve Courts sealed a good 4-1 win. Mevagissey ‘A’ and Bugle ‘B’ had a battle royale with the home side 3-2 winners. Paul Williams and Pete Chambers’ victories were cancelled out by Colin Rundle and Keith Moore great win over James Popplewell leaving Matt Mills’ good win over Mark Sturtridge deciding the result. The Runabout Shield in the Rees League is now at lowly Lostwithiel after they beat table toppers Mevagissey ‘C’. Three blackball frames all went the way of the visitors as Terry and Craig Nicholls and Darren Biggen’s single-point victory over Joe Chesterfield got them the win. Adrian Evans and ‘The Predator’ Tregale replied. That defeat allowed Bethel ‘C’ to draw level at the top after a great 4-1 win over their ‘B’ team. Courtney Crockford, Roger Smithson, Howard Brett and Leigh Rosevear all registered big wins with Clive Stuthridge continuing his good season seeing off Ben Stunnell. Lerryn picked up a great 3-2 win at Bethel ‘D’. Graham Hoskin and Matt Woodward traded frames with Dave Morshead and Jason Pascoe with Gavin Dyche unlucky to go in-off the black to gift Terry Middleton the win. Stacey Hancock beat Damian Knight to give Tregonissey ‘C’ a great start at Bugle ‘C’. But that was as good as it got for them despite Amanda Fleming pushing Luke Kennedy all the way as did Caz Stephens against Kev Spencer in the last match of the evening. Nigel Couchman and Roy Bayliss completed the home side.

FULL RESULTS

Victory League: Mevagissey ‘A’ 3 (P Williams, P Chambers, M Mills) Bugle ‘B’ 2 (C Rundle, K Moore), Bugle ‘A’ 2 (I Ball, A Best) Tregonissey ‘B’ 3 (P Hooley, A Gooch, M Hooley). Tregonissey ‘A’ 5 (J Cocks, J Simmons, R Pearson, R Bilson, B McIntosh (35)) Mevagissey ‘D’ 0, Pelynt 2 (R Broad, K Armatage) Bethel ‘A’ 3 (G Hawken, M Green, G Stephens), St Neot 4 (D Lock, M Vessey, A Maddams, S Courts) Mevagissey ‘B’ 1 (B Rothwell). Rees Memorial League: Bugle ‘C’ 4 (N Couchman, L Kennedy, R Bayliss, K Spencer) Tregonissey ‘C’ 1 (S Hancock), Mevagissey ‘C’ 2 (A Evans, D Tregale) Lostwithiel 3 (T Nicholls, C Nicholls, D Biggen), Bethel ‘C’ 4 (C Crockford, R Smithson, H Brett, L Rosevear) Bethel ‘B’ 1 (C Stuthridge), Bethel ‘D’ 2 (D Morshead, J Pascoe) Lerryn 3 (G Hoskin, M Woodward, T Middleton). Top breaks of the week: McIntosh 35 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Stuff of legend', 'stuff-of-legend', 'Professional Snooker', '[]'::jsonb, 'It was a game that had everything" may be one of sports most overused cliches but I honestly can''t think of any other way to describe the action in todays Shanghai Masters Final.', null, '"The record books will show that John Higgins beat Judd Trump 10-9 to win the title and in so doing clinch his 25th ranking event title."', 'It was a game that had everything" may be one of sports most overused cliches but I honestly can''t think of any other way to describe the action in todays Shanghai Masters Final.

Trump playing some beautifully flowing snooker races into lead

The record books will show that John Higgins beat Judd Trump 10-9 to win the title and in so doing clinch his 25th ranking event title.For once though that really only tells part of the story about a match that will have anyone lucky enough to have witnessed it talking for a long time. This close tight match didn''t look on the cards early on as Trump playing some beautifully flowing snooker raced into a 4-0 mid session interval lead and extended that to 5-0 in the next.Higgins though is never one panic and he got his first frame on the board in the next in the best possible way with a maximum 147 break which netted Higgins 12,000 and a box of six gold nuggets from the sponsors.The prize would not have been on his mind though as he lost the next to trail 6-1 and they shared the final two of the session to leave Trump within touching distance of the title leading 7-2. However as we had seen many times over the years you simply can never write off John Higgins and he again showed us why he is the great champion he is by coming out in the second session with all guns blazing.Breaks of 89,74 and 76 saw him win the first four frames of the night to close within one at the mid session interval,the score now 7-6 He wasn''t finished there however and won the next with a 71 and in an hard fought 15th frame Higgins doubled the final black to take the lead 8-7.Judd at this stage must have been in a daze wondering what was happening to him so it is to his credit as well as testament to his growing maturity that he constructed a fine 105 to again level at 8-8.

147 & SWEET WIN FOR HIGGINS

Both players were now showing fine touch albeit neither were experiencing the best run of the ball. Higgins was first in again in the next with 64 but Trump fought back and looked like he ma snatch it before undercutting the black trying to get back up for the yellow. Higgins took it to lead 9-8.Trump wasn''t done for yet though and he won a tense 18th frame to force a decider.which was no more then he deserved They say all you want in a deciding frame is to get a chance and that first chance fell to Trump but he could only manage 35 before running out of position..Higgins though came to the table and knocked in a superb red before running out the victor with a fine 61. This win will be made all the sweeter for Higgins not only because of the great comeback to win it but also because it proves to everyone and possibly even himself that he has still got a lot more to offer in the game.I certainly don''t think that any player will be relishing meeting him on the table for the rest of the season. For Trump he will no doubt be very disappointed to have let a 7-2 lead slip away but when he looks back on the match out of the heat of the battle he can reflect positively on the fact that this was Higgins winning the match not him losing it. He can also look back on a week where he has impressed everyone with his all round play and maybe once and for all put to bed the "one trick pony " label he has been unfairly branded with by some.He can take great confidence going on from this for the rest of the season. Finally I want to comment on the tournament as a whole. I think although this was actually the third ranking event of the season many will feel this is where the season finally caught fire.The crowds seemed good all week and the atmosphere for the final seemed to be electric. We now have a few PTC events before we return to China for the International Championship and the small matter of the return of our World Champion Ronnie O Sullivan.Get the fires lit and pull in the sofa we''re going to have super winter! Article courtesy of The Green Baize Snooker Blog Images Courtesy of: Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('Superb Hamilton wins first ranking title', 'superb-hamilton-wins-first-ranking-title', 'Professional Snooker', '[]'::jsonb, 'Anthony Hamilton won the first world ranking title of his 26-year professional career by beating Ali Carter 9-6 in the final of the F66.com German Masters.', null, '“It’s crazy to win a tournament when I’ve stopped thinking about how to do it,” said Hamilton, a four-time Crucible quarter-finalist. “I stopped wanting it so badly and that took the pressure off. It just feels strange to win another match and now I’m sitting here with a trophy. I’ve struggled for most of this week, but then found some form at the end from absolutely nowhere. I couldn’t pot a ball up until tonight, then played the best snooker of my life.', 'Anthony Hamilton won the first world ranking title of his 26-year professional career by beating Ali Carter 9-6 in the final of the F66.com German Masters.

more Hamilton played tremendous snooker in the closing stages at the Tempodrom in Berlin as he came from 5-2 down to win seven of the last eight frames. At the age of 45, the Nottingham cueman is the oldest winner of a ranking event since a 46-year-old Doug Mountjoy captured the 1989 Classic. And Hamilton has done it in fine style, beating the top two players in the world, Mark Selby and Stuart Bingham, as well as Mark Williams and Barry Hawkins, to reach the final before outplaying Carter when it mattered most. Victory gives Hamilton the biggest pay day of his career, 80,000 Euros, and he leaps from 66th to 38th in the world rankings. His triumph is all the more remarkable for the fact that last season he was almost relegated from the professional circuit, his game adversely affected by a chronic spinal condition. He had to win two matches at the 2016 Gdynia Open to keep his tour card, and he did just that. In recent months he has shown an improvement in form, notably reaching the semi-finals of the Northern Ireland Open in November. It was Mark King who went on to win that title in Belfast, and tonight produced a similar fairytale finish for a popular player who has fought hard on the tour for a quarter of a century to gain a deserved reward. This was Hamilton’s third ranking final and first for 15 years, having lost at the 1999 British Open to Fergal O’Brien and at the 2002 China Open against Mark Williams, when he crumbled under pressure and squandered an 8-5 lead. This time, he showed admirable composure when the winning line came into view. Previously regarded by most of his fellow pros as the best player never to win a ranking title, he has now shed that tag forever. Fittingly, his parents Cliff and Stella were among the enthusiastic crowd to see their son celebrate the best moment of his career. Carter missed out the chance to win a fifth world ranking title and to capture this crown for the second time having won it in 2013. The 37-year-old from Chelmsford had been bidding for a second ranking title of the season having landed the World Open in July. He lost a ranking final for the fourth time but still moves up from 14th to 11th in the world. Trailing 5-3 after the first session, Hamilton stormed back tonight by winning the first four frames in a row with breaks of 49, 118, 73 and 74. Carter made 53 in the next before missing the black off its spot, and Hamilton punished him with an excellent 70 clearance to go three up with four to play. In frame 14, Carter missed a red along the top cushion on 41, but this time the balls ran safe and he got another chance, adding 42 to cut his arrears to 8-6. But there was to be no fight back. Hamilton trapped his opponent in a snooker early in frame 15, and from the chance that followed he made a well-crafted 57, sinking a tricky plant on the third-last red which left Carter needing snookers. Shortly afterwards, the handshake came. “It’s crazy to win a tournament when I’ve stopped thinking about how to do it,” said Hamilton, a four-time Crucible quarter-finalist. “I stopped wanting it so badly and that took the pressure off. It just feels strange to win another match and now I’m sitting here with a trophy. I’ve struggled for most of this week, but then found some form at the end from absolutely nowhere. I couldn’t pot a ball up until tonight, then played the best snooker of my life. “The key moments were at 3-0 and 5-2 down because I was really tired, I was cueing badly. I won the last frame this afternoon for 5-3 – maybe if it had been 6-2 it was all over. When it was 8-5, that was the same score I had at the China Open in 2002 and I couldn’t keep that out of my mind. That just added to the stress, it was not a nice place to be. I just tried to concentrate and breathe properly and wait for a chance. “I’ve had some nice words from the players this week, especially Mark Selby, he was texting me saying he wanted me to win. I felt some support from the crowd today because I hadn’t won a title before and maybe that put some pressure on Ali. “My mum and dad were here for the first time, I just wanted them to see me play here once before I retire because it’s one of the best venues we’ve got. And how lucky that I ended up winning the tournament. “Last season I told myself to stop chucking the toys out of the pram and to try to do the right thing whatever happens. Just be calm and try to the end. If you drive home after a loss but you’ve tried your best, you can be happy.” Carter said: “I missed a plant at 5-2 when I could have gone 6-2 up, that was the key moment for me. Every credit to Anthony because he played well tonight. I didn’t feel I did that much wrong. I’m not the best loser in the world but I didn’t throw this one away. Getting to finals is great but it’s not what I’m here for. I have won one title this season and almost another so my game is in good shape.” Both players now head to the Ladbrokes World Grand Prix in Preston, which starts on Monday. Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Taylor''s no Turnip with fine 88-break', 'taylors-no-turnip-with-fine-88-break', 'Match Reports', '[]'::jsonb, 'An amazing penultimate week before the Christmas break saw Graham Taylor record the highest break so far with a majestic 88 against Steve Courts as St Blazey ‘B’ claimed a 4-1 victory over St Neot.', null, '"Every Victory League game ended 4-1 as Bugle ‘A’ recorded a good win at Bethel ‘A’ but as last night was their bye they would expect to drop to second place as Blazey were playing Bethel ‘D’, whose Andy Spearman recorded their only point at Bugle ‘B’."', 'An amazing penultimate week before the Christmas break saw Graham Taylor record the highest break so far with a majestic 88 against Steve Courts as St Blazey ‘B’ claimed a 4-1 victory over St Neot.

more The win keeps up the pressure on leaders Bugle ‘A’ and the league’s only unbeaten record went as Ian Wilton beat Mike Hancock to claim St Neot’s only point. Every Victory League game ended 4-1 as Bugle ‘A’ recorded a good win at Bethel ‘A’ but as last night was their bye they would expect to drop to second place as Blazey were playing Bethel ‘D’, whose Andy Spearman recorded their only point at Bugle ‘B’. Lostwithiel ‘A’ got a much-needed win at home to Mevagissey ‘A’ to pull themselves clear of the relegation zone as Northcott, Cock, Maddams and Perring were victorious with Mike Towsey replying and Tregonissey consolidating third place as Barry McIntosh’s 39 and victories for Jason Cocks, Chris Stephenson and Ryan Bison killed off St Blazey ‘A’ with Michael Meares replying. All Rees League games ended 3-2 one way or the other but with the top two of Bethel B and C having their bye week the table will look a lot closer after last night. Lerryn continued their good form to take two points off table topper Bethel ‘C’ with the reliable Gordon Brimcombe and Graham Hoskin recording victories whilst Bethel ‘B’ came from 2-0 down to pip Bugle ‘C’ to stay in contention. Mevagissey ‘B’ probably hoped for more at home to their ‘D’ side but a 3-2 reverse is a bit of a setback as Blamey, Tomlinson and Byard spoilt the party while Gorran Haven made the short trip to Mevagissey ‘C’ and returned home with two points as Lee McKinstry and Paul Grimmett were successful. The next committee meeting of the league will be held on Monday, January 6 at Bethel Social Club, from 7.30pm.

FULL RESULTS

Victory League: Bethel ‘A’ 1 (G Hawken) Bugle ‘A’ 4 (A Peers, I Powell, G Spencer, A Best (32)), Bugle ‘B’ 4 (J Moore, K Moore, I Ball, D Rundle) Bethel ‘D’ 1 (A Spearman), Lostwithiel ‘A’ 4 (D Northcott, D Lock, A Maddams, L Perring) Mevagissey ‘A’ 1 (M Towsey), St Blazey ‘B’ 4 (G Taylor (88), D Kirwan, A Gooch (33), P Baron (46) St Neot 1 (I Wilton), Tregonissey 4 (B McIntosh (39), J Cocks, C Stephenson, R Bilson) St Blazey ‘A’ 1 (M Meares). Rees Memorial League: Bethel ‘B’ 3 (G Buckle, S Hicks, M Green) Bugle ‘C’ 2 (N Couchman, M Sturtridge), Mevagissey ‘B’ 2 (M Gregory, D Kendall) Mevagissey ‘D’ 3 (R Blamey, J Tomlinson, M Byard), Lerryn 2 (G Brimicombe, G Hoskin) Bethel ‘C’ 3 (S Jones, C Crockford, R Smithson), Mevagissey ‘C’ 3 (D Tregale, J Chesterfield, C Prynn) Gorran Haven 2 (L McKinstry, P Grimmett). Top breaks of the week: G Taylor 88, A Best 32, A Gooch 33, P Baron 46 B McIntosh 39 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Team & Player profiles to feature ever week', 'team-player-profiles-to-feature-ever-week', 'Professional Snooker', '[]'::jsonb, 'Each week or when they become available from players we will be featuring our exclusive CUEVIEW interviews.', null, null, 'Each week or when they become available from players we will be featuring our exclusive CUEVIEW interviews.

more We have been very lucky so far to have several exclusives from professional snooker players, but the main idea behind CUEVIEW was to get as many players from the Victory & Rees Leagues to fill them in with as much detail as possible, so far we have had a good uptake especially as we are only into week 4 (writing this). Richard Pearson has been going round every week with his camera equipment taking photos of players, clubs and general action not only for the website but also for team profiles and individual profiles. We hope you enjoy reading them as they become available and it will also give you all an insight to the player and person who you might just come up against during the season.

Images Courtesy of: Richard Pearson If for some reason you haven''t been able to fill one of our CUEVIEW''s in then you can also do so by filling in the electronic version below.', '2014-01-01', false, 'Richard Pearson'),
  ('Team Handicap upsets', 'team-handicap-upsets', 'Competitions', '[]'::jsonb, 'The team handicap always throws up upsets and it proved to be the same as Bethel ‘A’, Mevagissey ‘A’, St Neot and holders Bugle ‘B’ all left the competition.', null, 'Mevagissey ‘D’ made a good start at Bethel ‘A’ as Mark Ashton defeated Gavin Dyche but that was as good as it got for them as Leon Collard, Matt Green, Geoff Hawken and Andy Peers, who sneaked past Rob Blamey got Bethel’s point which wasn’t a true reflection of the evening’s play.', 'The team handicap always throws up upsets and it proved to be the same as Bethel ‘A’, Mevagissey ‘A’, St Neot and holders Bugle ‘B’ all left the competition.

more Anthony Garside rolled back the years and put on a potting showcase as he beat Garry Stephens with Dan Polmounter potting pink and black to beat Geoff Hawken and with Rob Garside getting the better of Matt Green, St Stephen took the tie 3-0. Mevagissey ‘A’ only took four players to Pelynt and with Richard Broad hammering James Popperwell it was an uphill struggle. Paul Williams knocked in a 33 as he beat Andy Parnell but Chris Mitchell’s win against Phil Staley and the bye put them through. St Neot tasted defeat at Mevagissey ‘C’ as ‘The Predator’ Tregale took out Anthony Maddams with some remarkable potting. Steve Courts replied but Joe Chesterfield and Adrian ‘Hellfire’ Evans, who hammered Chris Perring, got the Rees boys through. Bugle ‘B’ went 2-0 up at Bethel ‘D’ through Mark Sturtridge and Colin Rundle but three really tight frames saw Gavin and Dyale Dyche level things up with Dave Morshead winning an entertaining game to see the holders out. Courtney Crockford gave away an amazing 48 points in fouls as he lost to Luke Kennedy as Bethel lost to Bugle ‘C’. Kevin Spencer put them 2-0 up but Roger Smithson pulled one back for the away side beating Damian Knight but Mo Roscorla beat Paul Thomas to see Bugle through. Treggy ‘A’ went to Gorran and cruised to a 2-0 lead through Chris Stephenson and Ryan Bilson’s black ball win over Andy Reddall. Lee McKinstry beat Richard Pearson to get a frame back but Barrie McIntosh’s 31 break made the difference as he beat Paul Grimmett. Mevagissey ‘B’ also progressed with a 3-1 victory at Lerryn.

ST BLAZEY AND DISTRICT SNOOKER LEAGUE TEAM HANDICAP:

Bugle ‘C’ 3 (L Kennedy, K Spencer, M Roscorla) Bethel ‘C 1 (R Smithson), Bethel ‘D’ 3 (G Dyche, D Dyche, D Morshead) Bugle ‘B’ 2 (M Sturtridge, C Rundle), Gorran 1 (L McKinstry) Tregonissey ‘A’ 3 (C Stephenson, R Bilson, B McIntosh), Pelynt 3 (R Broad, C Mitchell, P Ormond) Mevagissey ‘A’ 1 (P Williams), Bethel ‘A’ 0 St Stephen 3 (A Garside, D Polmounter, R Garside), Mevagissey ‘C’ 3 (D Tregale, J Chesterfield, A Evans) St Neot 1 (S Courts), Lerryn 1 Mevagissey ‘B’ 3. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Team handicap takes centre stage', 'team-handicap-takes-centre-stage', 'Competitions', '[]'::jsonb, 'There was only one league this week in the St Blazey and District Snooker League as the team handicap preliminary round was played.', null, null, 'There was only one league this week in the St Blazey and District Snooker League as the team handicap preliminary round was played.

more St Stephen ‘B’ recorded an excellent 3-1 home win over Mevagissey ‘B’. Dan Allen saw off Nathan Shaw in the first frame only for Ben Rothwell to level up after beating Anthony Garside but Anthony Harrison and Cary Clark beat Dave Kendall and Matt Rowe respectively to move the home side into the first round. Rober Bowes beat Chris Brown on the black to put St Stephen ‘B’ one-up at St Blazey ‘A’ only for Mickey Meares, Stewart Dewings and Leigh Rosevear to put the home side through with Craig Nicholls beating Nick Kendall in the dead-rubber game. Bethel ‘A’ saw off their ‘C’ team 3-0 at the Bethel Crucible. Andy Peers played well to win against fit-again Rogers Smithson and Gary Stephens beat Howard Brett, who will rue missing several chances with Geoff Hawken riding his luck to win against the very unlucky Courtney Crockford. Tregonissey ‘A’ progressed after winning 3-0 at Lerryn. In a re-arranged Reed League match Mevagissey ‘C’ recorded their first win of the season beating Bethel ‘B’ 4-1 with three frames going down to the black. Joe Chesterfield beat Dave Morshead in the first frame. Rich Allen was well ahead against Dave Tregale but the Predator produced a magnificent rearguard action to come strongly back to clinch the frame on the pink. Jim Tamblyn played well to defeat Charlie Prynn but Matt Chesterfield and Benjamin Prynn sneaked past Guy Buckle and Clive Stuthridge for a very good victory. Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Teams play off in cup semi-finals', 'teams-play-off-in-cup-semi-finals', 'Competitions', '[]'::jsonb, 'Two cup semi-finals and one league match was the only action this week.', null, null, 'Two cup semi-finals and one league match was the only action this week.

more In the team pairs Bugle ‘B’ held a 2-1 lead over their ‘A’ team but two big wins put the ‘A’ team 3-2 up with a 134-point advantage so the last game was conceded leaving the victors waiting for either Bethel ‘A’ or Tregonissey ‘A’ in the final, when they play on February 21. Bethel ‘B’ made a great start at St Blazey ‘A’ with Clive Stuthridge knocking in a 34 break when beating Aiden Maxwell-Craddock but captain Mickey Meares responded straight away knocking in a 47 while beating Jim Tamblyn. Further wins for Stewart Dewings and Nick Kendall saw the Blazey boys through to the final where they will play Bugle ‘B’, who beat Bethel ‘A’ 3-1 a couple of weeks ago. Mevagissey ‘A’ and Pelynt pulled their Victory League game forward a week and Meva’s 4-1 win saw them move back into second place in the league. James Popplwell got the better of Richard Broad in the opener with Len Flower beating Phil Staley to level things up. Leighton Varcoe’s close win over Andy Parnell was followed up by wins for Paul Williams and Matt Mills for the home side. The latest rankings are now online with the top 16 from each league invited to play in the Boynton Trophy tournament which is to be played on Saturday, April 1 with a 10am start. The league presentation night will be on April 8 with the Belfast Busker as entertainment. Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('The ''D'' boys win the battle of Meva', 'the-d-boys-win-the-battle-of-meva', 'Match Reports', '[]'::jsonb, 'Mevagissey ‘D’ produced another fighting display to beat their ‘B’ team by the odd frame.', null, 'Mevagissey ‘A’ remain third after comfortably defeating Pelynt 4-1. Phil Ormond took out Phil Staley in the last frame of the evening for the away point with Mills, Williams, Varcoe and Popplewell getting the home points.', 'Mevagissey ‘D’ produced another fighting display to beat their ‘B’ team by the odd frame.

more Ben Rothwell got the ‘B’ team off to a good start beating Rob Blamey, but wins for Rich Lakeman, Ian Latham and Scott Mills secured the win with Mark Gregory getting the better of Mark Ashton in the last. St Neot went home from Tregonissey ‘A’ with a 3-2 win and the Runabout Shield. Chris Perring’s great win against Jason Simmons got them going, but Treggy responded through Barrie McIntosh (36 break) and Ryan Bilson, but Darren Lock and Steve Courts took the last two frames for a great victory. Buge ‘A’ have moved level top with Treggy after defeating St Blazey 4-1. Close wins for Ian Ball over Mickey Meares and Gary Spencer over Nick Kendall along with wins from Andrew Best and Paul Sturtridge got these points with Chris Morford taking out Ian Powell for Blazey’s point. Mevagissey ‘A’ remain third after comfortably defeating Pelynt 4-1. Phil Ormond took out Phil Staley in the last frame of the evening for the away point with Mills, Williams, Varcoe and Popplewell getting the home points. Garry Stephens with a 32 and Andy Peers with a 36 helped Bethel ‘A’ defeat Bugle ‘B’ 4-1. Other wins for Matt Green over Mark Sturtridge and Leon Collard’s victory against Keith Moore got the win. Dave Rundle’s black ball win over Geoff Hawken got Bugle’s point. Mevagissey ‘C’ hold on to top spot in the Rees League after overcoming Gorran 3-2. Lee McKinstry beat Ben Prynn 84-57 in the opener and Andy Reddall beat Adrian Evans in the last. But wins for ‘Predator’ Tregale and Joe and Matt Chesterfield keeps them flying high. Bethel ‘C’ sit second after defeating Tregonissey ‘C’ 5-0 in a re-arranged game but suffered defeat at Bugle ‘C’ last Tuesday. Mo Roscorla, Nigel Couchman and Luke Kennedy got the home wins with Ben Stunnell and Leigh Rosevear replying. Anthony Garside knocked in a 34 break as St Stephen beat Lerryn 3-2. Son Rob Garside also won along with Anthony Harrison with Matt Woodward and Trevor Pearce replying. Carol Stephens had a walkover after Bethel ‘B’ could only muster four players. But all four still won to get a good win, Guy Buckle, Martin Isted, Clive Stuthridge and Richard Bolt were their marksmen.

FULL RESULTS

Victory League: Mevagissey ‘A’ 4 (M Mills, P Williams, L Varcoe, J Popplewell) Pelynt 1 (P Ormand), Bugle ‘A’ 4 (I Ball, A Best, P Sturtridge, G Spencer) St Blazey 1 (C Morford), Tregonissey ‘A’ 2 (B McIntosh (36), R Bilson) St Neot 3 (C Perring, D Lock, S Courts), Mevagissey ‘D’ 3 (R Lakeman, I Latham, S Mills) Mevagissey ‘B’ 2 (B Rothwell, M Gregory), Bethel ‘A’ 4 (M Green, G Stephens (32), L Collard, A Peers (36) Bugle ‘B’ 1 (D Rundle). Rees Memorial League: Gorran 2 (L McKinstry, A Reddall) Mevagissey ‘C’ 3 (D Tregale, M Chesterfield, J Chesterfield), Bugle ‘C’ 3 (M Roscorla, N Couchman, L Kennedy) Bethel ‘C’ 2 (B Stunnell, L Rosevear), St Stephen 3 (A Garside (34), R Garside, A Harrison) Lerryn 2 (M Woodward, T Pearce), Bethel ‘B’ 4 (G Buckle, M Isted, C Stuthridge, R Bolt) Tregonissey ‘C’ 1 (C Stephens), Bethel ‘C’ 5 (H Brett, B Stunnell, C Crockford, R Smithson, L Rosevear) Tregonissey ‘C’ 0. Top breaks of the week: B McIntosh 36, G Stephens 32, A Peers 36, A Garside 34 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('The Big Break Club', 'the-big-break-club', 'League News', '[]'::jsonb, 'Snooker Roadshows, Dates, Venues all the information you need', null, '"Cornwall amateur billiards and snooker association has the ambition to develop a youth team that has the potential to represent Cornwall both locally and nationally. The association is currently hosting a variety of events that aim to increase knowledge of opportunities for coaching and competitions. If you would like your child to attend please complete the details below."', 'Snooker Roadshows, Dates, Venues all the information you need

CORNWALL AMATEUR BILLIARDS & SNOOKER ASSOCIATION PRESENTS

THE BIG BREAK CLUB

Snooker Roadshows - Dates and Venues Saturday 2nd February @ St Rumons - Redruth 11:00am - 2:00pm St Rumons, Penryn Street, Redruth, TR15 2SP Sunday 10th March @ Tregonissey Social Club - 11:30am - 3:00pm 121 Tregonissey Road, St Austell, PL25 4DS Saturday 30th March @ St Neot Village Institute - 11:30am - 3:00pm St Neot, Liskeard, PL14 6NG Follow the events on: @bigbreakclub

INFORMATION FOR PARENTS

Cornwall amateur billiards and snooker association has the ambition to develop a youth team that has the potential to represent Cornwall both locally and nationally. The association is currently hosting a variety of events that aim to increase knowledge of opportunities for coaching and competitions. If you would like your child to attend please complete the details below.

INFORMATION FOR YOUNG PLAYERS

